55	static int simple_entropy_func(void* data, unsigned char* output, size_t len)
56	{
57	    (void)data;
58	    if (agent_secure_random(output, len) == 0) {
59	        return 0;
60	    }
61	    /* No fallback — cryptographic entropy is mandatory for TLS.
62	     * Returning an error forces the TLS handshake to fail safely
63	     * rather than proceeding with predictable key material. */
64	    syslog(LOG_ERR, "[vela_tls] CRITICAL: No secure entropy source available\n");
65	    return -1;  /* Generic error - TLS handshake will fail safely */
66	}
