154	static void tls_ctx_free(tls_ctx_t* ctx)
155	{
156	    if (ctx->abort_on_close) {
157	#ifdef CONFIG_NET_SOLINGER
158	        if (ctx->net.fd >= 0) {
159	            struct linger abort = {1, 0};
160	            setsockopt(ctx->net.fd, SOL_SOCKET, SO_LINGER, &abort, sizeof(abort));
161	        }
162	#endif
163	    } else {
164	        mbedtls_ssl_close_notify(&ctx->ssl);
165	    }
166	    /* close_notify already finishes TLS.  A separate shutdown followed by
167	     * close schedules overlapping TCP callbacks on NuttX, and controlled
168	     * callers used to shut down twice.  Close the socket exactly once. */
169	    mbedtls_net_close(&ctx->net);
170	    mbedtls_ssl_free(&ctx->ssl);
171	    mbedtls_ssl_config_free(&ctx->cfg);
172	    mbedtls_ctr_drbg_free(&ctx->ctr_drbg);
173	
174	#ifdef CONFIG_AI_AGENT_NET_RPMSG
175	    network_release_resource();
176	#endif
177	}
