    size_t i = 0;
    while (i < n) {
        size_t take = n - i > 48 ? 48 : n - i;
        size_t o = 0;
        for (size_t j = 0; j < take; j += 3) {
            uint32_t v = p[i+j] << 16;
            if (j+1 < take) v |= p[i+j+1] << 8;
            if (j+2 < take) v |= p[i+j+2];
            chunk[o++] = t[(v>>18)&63]; chunk[o++] = t[(v>>12)&63];
            chunk[o++] = (j+1 < take) ? t[(v>>6)&63] : '=';
            chunk[o++] = (j+2 < take) ? t[v&63] : '=';
