    mkdir(FORENSIC_DIR, 0755);
    mkdir(dir, 0755);

    char path[64];
    FILE* f;
    snprintf(path, sizeof(path), "%s/meta.txt", dir);
    if ((f = fopen(path, "w")) != NULL) {
        fprintf(f, "seq %u\nret -0x%04x\nhost %s\ntime %ld\n",
            s_frn.seq, -ret, host, (long)time(NULL));
