        table = {0x04: ("sha256", "rsa_pss"), 0x05: ("sha384", "rsa_pss"),
                 0x06: ("sha512", "rsa_pss")}
        return table.get(b1)
    classic_hash = {0x02: "sha1", 0x03: "sha224", 0x04: "sha256",
                    0x05: "sha384", 0x06: "sha512"}.get(b0)
    classic_sig = {0x01: "rsa_pkcs1", 0x03: "ecdsa"}.get(b1)
    if classic_hash and classic_sig:
